def fibonacci(n):
    """
    Returns the nth Fibonacci number.
    fibonacci(0) is 0 and fibonacci(1) is 1.
    """
    if n < 0:
        raise ValueError("Fibonacci index cannot be negative")
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        # Recursive solution with memoization to avoid repeated work
        memo = {0: 0, 1: 1}
        def fib_helper(k):
            if k in memo:
                return memo[k]
            else:
                memo[k] = fib_helper(k-1) + fib_helper(k-2)
                return memo[k]
        return fib_helper(n)
```

